    for r in (0, h - 1):
        cells = [c for c in range(w) if grid[r][c] != bg]
        if cells:
            bars.append((r, min(cells), max(cells)))
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or any(grid[r][c] == grid[br][lo] for br, lo, hi in bars):
                continue
            # Treat non-background isolated cells as ray markers, excluding the bars.
            if any(r == br and lo <= c <= hi for br, lo, hi in bars):
                continue
            color = grid[r][c]
            if color not in (0, 6, 7):
                continue
            out[r][c] = 4
            if bars:
                br, lo, hi = min(bars, key=lambda b: abs(r - b[0]))
                cc = min(max(c, lo), hi)
                step = -1 if br < r else 1
                rr = r + step
                while 0 <= rr < h and rr != br:
                    out[rr][cc] = color
                    rr += step
    return out
